import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"下载与系统要求","description":"","frontmatter":{},"headers":[],"relativePath":"zh/download.md","filePath":"zh/download.md","lastUpdated":null}'),l={name:"zh/download.md"};function r(i,e,s,c,n,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="下载与系统要求" tabindex="-1">下载与系统要求 <a class="header-anchor" href="#下载与系统要求" aria-label="Permalink to &quot;下载与系统要求&quot;">​</a></h1><p>DeepSeek Harness Shell 是跨平台桌面应用（Windows / macOS / Linux），安装包发布在 GitHub Releases。</p><h2 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to &quot;版本&quot;">​</a></h2><p>当前文档对应版本：<strong>0.1.5-alpha-3</strong>。</p><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>操作系统</td><td>Windows 10/11（x64、arm64）、macOS、主流 Linux（x64、arm64）</td></tr><tr><td>运行时</td><td>无需预装 Node.js（自带 <code>@deepseek-ai/dsh</code> 内核管理）</td></tr><tr><td>网络</td><td>首次需联网以下载 / 安装 dsh 内核；后续使用本地回环地址</td></tr></tbody></table><blockquote><p>内核 <code>@deepseek-ai/dsh</code> 由应用自动检测；缺失时应用内会引导一键安装（可选官方 registry.npmjs.org 或 npmmirror 镜像）。</p></blockquote><h2 id="从哪里下载" tabindex="-1">从哪里下载 <a class="header-anchor" href="#从哪里下载" aria-label="Permalink to &quot;从哪里下载&quot;">​</a></h2><ul><li>打开 <a href="https://github.com/XEonSKY/DeepSeek-Harness-Shell/releases" target="_blank" rel="noreferrer">Releases</a> 页面，选择最新版本。</li><li>产物命名形如：<code>DeepSeek-Harness-Shell-&lt;版本&gt;-&lt;平台&gt;-&lt;架构&gt;.&lt;后缀&gt;</code><ul><li>Windows 安装包：<code>...-win-x64-setup.exe</code> / <code>...-win-arm64-setup.exe</code></li><li>macOS：<code>...-mac-x64.dmg</code> / <code>...-mac-arm64.dmg</code>（同版本另有 <code>.zip</code>，供自动更新使用）</li><li>Linux：<code>...-linux-x64.AppImage</code> / <code>...-linux-arm64.AppImage</code></li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">选择架构</p><p>按你<strong>运行的进程架构</strong>（即安装包架构）匹配资产：ARM 机器请下载 arm64 版，Intel/AMD 请下载 x64 版。</p></div><h2 id="验证与安全" tabindex="-1">验证与安全 <a class="header-anchor" href="#验证与安全" aria-label="Permalink to &quot;验证与安全&quot;">​</a></h2><ul><li>建议仅从官方 Releases 下载；应用自更新同样走 GitHub 发布。</li><li>若所在网络访问 GitHub 较慢，可在「设置 → 网络 → GitHub 镜像」填入公共镜像前缀（如 <code>https://ghproxy.com</code>）来加速更新包的下载；留空即直连。</li><li>安装后如有「未知发行者」提示，请按系统引导放行（开源应用常未付费签名）。</li></ul>',12)])])}const m=t(l,[["render",r]]);export{u as __pageData,m as default};
